  hanbokhanger: { cat: 'theme', name: '한복 걸이', emoji: '👘', w: 1, d: 1, colors: [P.pink, P.mint, P.yel], build(c) { const g = new THREE.Group(); g.add(at(cyl(.15, .17, .04, P.dark, 12), 0, .02, 0), at(cyl(.015, .015, 1.5, P.dark, 6), 0, .75, 0), rot(at(cyl(.012, .012, .5, P.dark, 6), 0, 1.45, 0), 'z', Math.PI / 2)); const sk = cone(.32, .8, c, 20); sk.position.y = .55; sk.castShadow = true; g.add(sk); g.add(at(box(.46, .3, .2, shade(c, .35), .06), 0, 1.1, 0)); for (const x of [-1, 1]) g.add(rot(at(box(.12, .34, .16, shade(c, .35), .05), x * .3, 1.12, 0), 'z', -x * .5)); g.add(at(box(.08, .3, .02, P.red, .02), .06, .92, .11)); return g; } },
  soccerball: { cat: 'theme', name: '축구공', emoji: '⚽', w: 1, d: 1, colors: [P.white], build(c) { const g = new THREE.Group(); g.add(at(sph(.16, c, 16, 12), 0, .16, 0)); for (let i = 0; i < 6; i++) { const a = i * 2.1, e = (i % 3 - 1) * .7; const v = new THREE.Vector3(Math.cos(a) * Math.cos(e), Math.sin(e), Math.sin(a) * Math.cos(e)); const pt = sph(.045, '#2B2D4A', 8, 6); pt.scale.set(1, .3, 1); pt.position.copy(v.clone().multiplyScalar(.15)).add(new THREE.Vector3(0, .16, 0)); pt.lookAt(new THREE.Vector3(0, .16, 0)); pt.rotateX(Math.PI / 2); g.add(pt); } return g; } },
