  reindeer: { cat: 'theme', name: '루돌프 인형', emoji: '🦌', w: 1, d: 1, colors: ['#B87A4A'], build(c) { const g = plush(c, .9, false); for (const x of [-1, 1]) g.add(at(sph(.025, '#3B2F5E', 8, 6), x * .06, .56, .17)); g.add(at(sph(.04, P.red, 8, 6), 0, .49, .2)); for (const x of [-1, 1]) { g.add(rot(at(cyl(.012, .012, .2, '#8C5A3C', 5), x * .08, .8, 0), 'z', -x * .3), rot(at(cyl(.01, .01, .1, '#8C5A3C', 5), x * .13, .84, 0), 'z', -x * 1.2)); } return g; } },
  candycane: { cat: 'theme', name: '지팡이 사탕', emoji: '🍭', w: 1, d: 1, colors: [P.red], build(c) { const g = new THREE.Group(); const cur = new THREE.CatmullRomCurve3([new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, .7, 0), new THREE.Vector3(.05, .9, 0), new THREE.Vector3(.2, .92, 0), new THREE.Vector3(.3, .8, 0)]); g.add(new THREE.Mesh(new THREE.TubeGeometry(cur, 16, .05, 8, false), toon(P.white))); for (let i = 0; i < 10; i++) { const p = cur.getPoint(i / 10 + .04); const t = cur.getTangent(i / 10 + .04); const s2 = new THREE.Mesh(new THREE.TorusGeometry(.052, .012, 6, 12), toon(c)); s2.position.copy(p); s2.lookAt(p.clone().add(t)); g.add(s2); } g.add(at(cyl(.1, .12, .04, P.green, 12), 0, .02, 0)); return g; } },
