  bg_firefly: { cat: 'deco', name: '반딧불이', emoji: '✨', w: 1, d: 1, colors: [P.yel], build(c) { const g = new THREE.Group(); const j = new THREE.Mesh(new THREE.CylinderGeometry(.13, .13, .3, 14), new THREE.MeshToonMaterial({ color: '#CFE7FA', gradientMap, transparent: true, opacity: .3 })); j.position.y = .15; g.add(j); g.add(at(cyl(.14, .14, .03, P.wood, 14), 0, .31, 0)); for (let i = 0; i < 4; i++) { const f = new THREE.Mesh(new THREE.SphereGeometry(.02, 6, 5), new THREE.MeshToonMaterial({ color: c, gradientMap, emissive: c, emissiveIntensity: 1 })); f.position.set((i % 2 ? .05 : -.05), .1 + i * .05, (i % 3 - 1) * .04); f.name = 'bulbs'; f.userData.ph = i; g.add(f); } const pl = new THREE.PointLight(c, 0, 1.5, 2); pl.position.y = .15; pl.name = 'bulb'; g.add(pl); return g; } },
