  utensils: { cat: 'wall', wall: true, name: '조리도구 걸이', emoji: '🥄', w: .9, h: .5, z: 2.3, colors: [P.gray], build(c) { const g = new THREE.Group(); g.add(rot(at(cyl(.012, .012, .9, c, 6), 0, .2, .06), 'z', Math.PI / 2)); for (let i = 0; i < 4; i++) { const x = -.33 + i * .22; g.add(at(cyl(.01, .01, .3, c, 6), x, .02, .06)); if (i === 0) g.add(at(sph(.05, c, 10, 8), x, -.15, .06)); else if (i === 1) g.add(at(box(.08, .1, .01, c, .01), x, -.15, .06)); else if (i === 2) g.add(at(cyl(.06, .06, .01, c, 12), x, -.15, .06)); else g.add(at(box(.06, .1, .01, P.wood, .01), x, -.15, .06)); } return g; } },
